    createItem: function(type) {
        var fn = function() {
            var selected = grid.getSelectionModel().getSelected();

            if(selected) {
                this._createItem(selected.get('path'), wnd);
            }
            else
                Ext.Msg.show({
                    title: 'Criando documento',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Primeiro selecione um dos tipos de documetos, para ser criado.'
                });
        };

        var me = this;

        var grid = Ext._create('judicial.params.GlosaryGrid', {
            region: 'center',
            allowCreate: false,
            allowUpdate: false,
            allowRemove: false,
            doubleClickHandler: function() {
                fn.call(me);
            },
        });

        grid.getToolbar().remove(0);
        grid.getToolbar().get(1).setWidth(540);

        if(type!==undefined)
            grid.setFilterProperty('meaning_type', type, 1000);

        grid.setFilterProperty('active', true, 1001);

        var wnd = Ext._create('Ext.Window', {
            width: 600,
            height: 400,
            modal: true,
            border: false,
            layout: 'border',
            title: 'Criar novo',
            items: grid,
            buttons: [
                {
                    text: 'Criar',
                    scope: this,
                    handler: fn
                },
                {
                    text: 'Cancelar',
                    handler: function() { wnd.close(); }
                }
            ]
        });

        wnd.show();
    },

    rendererEventControl: function(value) {
        var number_control;
        var lawsuit = this.getParams().lawsuit;

        (value || []).forEach(
            function(ec) {
                if(ec.lawsuit === lawsuit)
                    number_control = ec.number_control;
            }
        );

        return '<div style="text-align: right">' + (number_control ? number_control : '?') + '</div>';
    },

    renderFileSize: function(value) {
        return [
            '<div style="text-align: right">',
                Ext.util.Format.fileSize(value),
            '</div>'
        ].join('');
    },

    formatColumnIcons: function(value, metaData, record, rowIndex, colIndex, store) {
        function rendererIconGrid(icons) {
            return icons
                .filter(
                    function(icon) { return icon !== null }
                )
                .map(function(icon) {
                    return [
                        '<div style="width:16px;height:16px;margin-right:3px" class="' + icon.iconCls + '" title="' +  icon.title + '">',
                        '</div>'
                    ].join('');
                })
                .join('');
        }

        var iconsCode = rendererIconGrid(value);
        var reminderCode = '';
        var titles = record.get('titles_reminders');
        var countReminder = titles.length;

        if (countReminder > 0) {
            reminderCode = [
                '<span class="badge badge-warning" ext:qtip="' + titles.join('<br/>') + '">',
                    countReminder > 9 ? '+9' : countReminder,
                '</span>'
            ].join('');
        }

        return [
            '<div style="display: flex; align-items: center; justify-items: center">',
                iconsCode,
                reminderCode,
            '</div>'
        ].join('');
    },

    getColumnModel: function() {
        var me = this;

        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    {
                        header: "Evento",
                        dataIndex: 'event_control',
                        width: 30,
                        menuDisabled: true,
                        renderer: function(v) { return me.rendererEventControl(v); }
                    },
                    {
                        header: '',
                        dataIndex: 'icons',
                        width: 70,
                        menuDisabled: true,
                        renderer: this.formatColumnIcons
                    },
                    {header: 'Documento', dataIndex: 'unicode', id: 'autoExpandColumn'},
                    {header: 'Modificado por', hidden: true, dataIndex: 'modified_by_unicode', width: 120},
                    {header: 'Modificado', hidden: true, dataIndex: 'modified_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {header: 'Criado por', hidden: true, dataIndex: 'created_by_unicode', width: 120},
                    {header: 'Criado', hidden: true, dataIndex: 'created_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {header: 'Assinado por', dataIndex: 'signed_by_unicode', width: 120},
                    {header: 'Assinado', dataIndex: 'signed_at', width: 100, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {header: 'Tamanho', dataIndex: 'size_cache', width: 65, renderer: this.renderFileSize },
                ]
            );

        return this._columnModel;
    },

